centers=[]
for i in range(R):
 for j in range(C):
  if g[i][j]==2 and any(0<=i+di<R and 0<=j+dj<C and g[i+di][j+dj]==3 for di in (-1,0,1) for dj in (-1,0,1)):
   centers.append((i,j))
out=[row[:] for row in g]
for i,j in centers:
 for x in range(max(0,i-1),min(R,i+2)):
  for y in range(max(0,j-1),min(C,j+2)):
   if out[x][y]!=2: out[x][y]=1
centers, '\n'.join(' '.join(map(str,row)) for row in out)

